mapper.select:
select 
from t_r_data_perm_user_direct_grant g
left join t_r_data_perm_scope sc on sc.code = g.scope_code
where g.user_id = #{userId}
  and g.effective_time <= #{asOf}
  and (g.expiration_time is null or g.expiration_time > #{asOf})

select min(effective_time)                                      as effectiveTime,
       case when max(case when expiration_time is null then 1 else 0 end) = 1
            then null
            else max(expiration_time)
       end                                                      as expirationTime,
       count(*)                                                 as permCount
from t_r_data_perm_user_direct_grant
where user_id = #{userId}
  and effective_time <= #{asOf}
  and (expiration_time is null or expiration_time > #{asOf})
having count(*) > 0
